"""CPU map backend: the versioned control-plane agent.

Owns resident immutable images, live process identities, request contexts,
connection generations, retained packets and current inode generations.  Every
precondition failure returns ``{"error":"rejected"}`` and changes nothing,
including high-water counters and capacity.
"""

import struct

from syntax import PolicyError, parse_policy
from compiler.compiler import CompileError, compile_policy

DENY = 4294967295

OK = {'ok': True}
REJECTED = {'error': 'rejected'}
_TAG = struct.Struct('>4sIIIII')
_HEADER = b'EMC4'

STAGE = 'stage'
COMMIT = 'commit'
RETIRE = 'retire'
SPAWN = 'spawn'
CLONE = 'clone'
EXIT = 'exit'
BEGIN = 'begin'
FINISH = 'finish'
OPEN = 'open'
SEND = 'send'
RECV = 'recv'
CLOSE = 'close'
STORE = 'store'
LOAD = 'load'
UNLINK = 'unlink'
INSPECT = 'inspect'


class Agent(object):
    """Replay engine for one job.  Jobs never share state."""

    def __init__(self, services, limits, cache=None):
        ordered = [service['name'] for service in
                   sorted(services, key=lambda item: item['label'])]
        self.order = ordered
        self.column = {}
        for slot, name in enumerate(ordered):
            self.column[name] = slot
        self.label = {}
        for service in services:
            self.label[service['name']] = service['label']
        self.limits = limits
        self.cache = {} if cache is None else cache
        self.images = {}
        self.active = None
        self.epoch_hwm = 0
        self.cells = 0
        self.units = {}
        self.unit_gen = {}
        self.connections = {}
        self.connection_gen = {}
        self.files = {}
        self.file_gen = {}
        self.live_units = 0
        self.live_contexts = 0
        self.live_connections = 0
        self.live_packets = 0
        self.live_files = 0
        self.context_id = 0
        self.published = {}
        self._handlers = {
            STAGE: self._stage, COMMIT: self._commit, RETIRE: self._retire,
            SPAWN: self._spawn, CLONE: self._clone, EXIT: self._exit,
            BEGIN: self._begin, FINISH: self._finish, OPEN: self._open,
            SEND: self._send, RECV: self._recv, CLOSE: self._close,
            STORE: self._store, LOAD: self._load, UNLINK: self._unlink,
            INSPECT: self._inspect,
        }

    # -- helpers ---------------------------------------------------------
    def _unit(self, identity):
        found = self.units.get((identity[0], identity[1]))
        if found is None or found[0] != identity[2]:
            return None
        return found

    def _connection(self, identity):
        found = self.connections.get(identity[0])
        if found is None or found[0] != identity[1]:
            return None
        return found

    def _file(self, identity):
        found = self.files.get(identity[0])
        if found is None or found[0] != identity[1]:
            return None
        return found

    def _advance(self, epoch, state, service):
        if state == DENY:
            return DENY
        return self.images[epoch][1][state][self.column[service]]

    def _new_context(self, unit, rid, epoch, state):
        self.context_id += 1
        unit[3][rid] = (epoch, state, self.context_id)
        unit[2] = rid
        self.live_contexts += 1
        self.images[epoch][3] += 1

    # -- image lifecycle -------------------------------------------------
    def _stage(self, event):
        epoch = event['epoch']
        if epoch <= self.epoch_hwm:
            return REJECTED
        text = event['policy']
        parsed = self.cache.get(text, False)
        if parsed is False:
            try:
                parsed = parse_policy(text)
            except PolicyError:
                parsed = None
            self.cache[text] = parsed
        if parsed is None:
            return REJECTED
        if text in self.published:
            machine = self.published[text]
        else:
            try:
                machine = compile_policy(parsed[0], self.order, self.column)
            except CompileError:
                machine = None
            self.published[text] = machine
        if machine is None:
            return REJECTED
        if len(self.images) >= self.limits['images']:
            return REJECTED
        cells = machine[2]
        if self.cells + cells > self.limits['cells']:
            return REJECTED
        accept, rows = machine[0], machine[1]
        self.images[epoch] = [accept, rows, cells, 0]
        self.epoch_hwm = epoch
        self.cells += cells
        return {'ok': True, 'epoch': epoch,
                'image': {'accept': accept, 'rows': rows}}

    def _commit(self, event):
        epoch = event['epoch']
        if epoch not in self.images:
            return REJECTED
        self.active = epoch
        return OK

    def _retire(self, event):
        epoch = event['epoch']
        resident = self.images.get(epoch)
        if resident is None or epoch == self.active or resident[3]:
            return REJECTED
        del self.images[epoch]
        self.cells -= resident[2]
        return OK

    # -- process identities ---------------------------------------------
    def _spawn(self, event):
        namespace, pid, generation = event['unit']
        key = (namespace, pid)
        if key in self.units:
            return REJECTED
        if generation <= self.unit_gen.get(key, 0):
            return REJECTED
        service = event['service']
        if service not in self.column:
            return REJECTED
        if self.live_units >= self.limits['units']:
            return REJECTED
        self.units[key] = [generation, service, 0, {}]
        self.unit_gen[key] = generation
        self.live_units += 1
        return OK

    def _clone(self, event):
        parent = self._unit(event['parent'])
        if parent is None:
            return REJECTED
        namespace, pid, generation = event['child']
        key = (namespace, pid)
        if key in self.units:
            return REJECTED
        if generation <= self.unit_gen.get(key, 0):
            return REJECTED
        if self.live_units >= self.limits['units']:
            return REJECTED
        source = parent[3]
        if self.live_contexts + len(source) > self.limits['contexts']:
            return REJECTED
        child = [generation, parent[1], parent[2], {}]
        copies = child[3]
        for rid, context in source.items():
            self.context_id += 1
            copies[rid] = (context[0], context[1], self.context_id)
            self.images[context[0]][3] += 1
        self.live_contexts += len(source)
        self.units[key] = child
        self.unit_gen[key] = generation
        self.live_units += 1
        return OK

    def _exit(self, event):
        unit = self._unit(event['unit'])
        if unit is None:
            return REJECTED
        contexts = unit[3]
        for context in contexts.values():
            self.images[context[0]][3] -= 1
        self.live_contexts -= len(contexts)
        del self.units[(event['unit'][0], event['unit'][1])]
        self.live_units -= 1
        return OK

    # -- request contexts ------------------------------------------------
    def _begin(self, event):
        unit = self._unit(event['unit'])
        if unit is None or self.active is None:
            return REJECTED
        rid = event['rid']
        if rid <= unit[2]:
            return REJECTED
        if self.live_contexts >= self.limits['contexts']:
            return REJECTED
        epoch = self.active
        state = self._advance(epoch, 0, unit[1])
        self._new_context(unit, rid, epoch, state)
        return {'ok': True, 'epoch': epoch, 'state': state}

    def _finish(self, event):
        unit = self._unit(event['unit'])
        if unit is None:
            return REJECTED
        context = unit[3].pop(event['rid'], None)
        if context is None:
            return REJECTED
        self.live_contexts -= 1
        self.images[context[0]][3] -= 1
        state = context[1]
        allowed = False if state == DENY else self.images[context[0]][0][state]
        return {'ok': True, 'allow': allowed}

    # -- transport -------------------------------------------------------
    def _open(self, event):
        ident, generation = event['connection']
        if ident in self.connections:
            return REJECTED
        if generation <= self.connection_gen.get(ident, 0):
            return REJECTED
        if self.live_connections >= self.limits['connections']:
            return REJECTED
        self.connections[ident] = [generation, 0, {}]
        self.connection_gen[ident] = generation
        self.live_connections += 1
        return OK

    def _send(self, event):
        unit = self._unit(event['unit'])
        connection = self._connection(event['connection'])
        if unit is None or connection is None:
            return REJECTED
        context = unit[3].get(event['rid'])
        if context is None:
            return REJECTED
        destination = event['destination']
        if destination not in self.column:
            return REJECTED
        stream = event['stream']
        if stream <= connection[1]:
            return REJECTED
        if self.live_packets >= self.limits['packets']:
            return REJECTED
        epoch, state = context[0], context[1]
        wire = _TAG.pack(_HEADER, epoch, state, self.label[destination],
                         stream, connection[0]).hex()
        connection[2][stream] = [epoch, state, destination, None]
        connection[1] = stream
        self.live_packets += 1
        self.images[epoch][3] += 1
        return {'ok': True, 'wire': wire}

    def _recv(self, event):
        connection = self._connection(event['connection'])
        if connection is None:
            return REJECTED
        packet = connection[2].get(event['stream'])
        if packet is None:
            return REJECTED
        unit = self._unit(event['unit'])
        if unit is None or unit[1] != packet[2]:
            return REJECTED
        explicit = event['wire']
        if explicit is not None:
            if (len(explicit) != 48 or
                    explicit.lower() != _TAG.pack(_HEADER, packet[0],
                                                  packet[1],
                                                  self.label[packet[2]],
                                                  event['stream'],
                                                  connection[0]).hex()):
                return REJECTED
        receipt = packet[3]
        rid = event['rid']
        if receipt is not None:
            if (receipt[0] == event['unit'][0] and receipt[1] == event['unit'][1]
                    and receipt[2] == rid):
                context = unit[3].get(rid)
                if context is not None and context[2] == receipt[3]:
                    return {'ok': True, 'epoch': receipt[4], 'state': receipt[5]}
            return REJECTED
        if rid <= unit[2]:
            return REJECTED
        if self.live_contexts >= self.limits['contexts']:
            return REJECTED
        epoch = packet[0]
        state = self._advance(epoch, packet[1], unit[1])
        self._new_context(unit, rid, epoch, state)
        packet[3] = (event['unit'][0], event['unit'][1], rid,
                     self.context_id, epoch, state)
        return {'ok': True, 'epoch': epoch, 'state': state}

    def _close(self, event):
        connection = self._connection(event['connection'])
        if connection is None:
            return REJECTED
        packets = connection[2]
        for packet in packets.values():
            self.images[packet[0]][3] -= 1
        self.live_packets -= len(packets)
        del self.connections[event['connection'][0]]
        self.live_connections -= 1
        return OK

    # -- file mediated handoff -------------------------------------------
    def _store(self, event):
        unit = self._unit(event['unit'])
        if unit is None:
            return REJECTED
        context = unit[3].get(event['rid'])
        if context is None:
            return REJECTED
        ident, generation = event['file']
        epoch, state = context[0], context[1]
        current = self.files.get(ident)
        if current is None:
            if generation <= self.file_gen.get(ident, 0):
                return REJECTED
            if self.live_files >= self.limits['files']:
                return REJECTED
            self.files[ident] = [generation, epoch, state]
            self.file_gen[ident] = generation
            self.live_files += 1
            self.images[epoch][3] += 1
            return OK
        if current[0] != generation:
            return REJECTED
        previous = current[1]
        self.images[previous][3] -= 1
        current[1] = epoch
        current[2] = state
        if epoch != previous:
            self.images[epoch][3] += 1
        return OK

    def _load(self, event):
        current = self._file(event['file'])
        if current is None:
            return REJECTED
        unit = self._unit(event['unit'])
        if unit is None:
            return REJECTED
        rid = event['rid']
        if rid <= unit[2]:
            return REJECTED
        if self.live_contexts >= self.limits['contexts']:
            return REJECTED
        epoch = current[1]
        state = self._advance(epoch, current[2], unit[1])
        self._new_context(unit, rid, epoch, state)
        return {'ok': True, 'epoch': epoch, 'state': state}

    def _unlink(self, event):
        current = self._file(event['file'])
        if current is None:
            return REJECTED
        del self.files[event['file'][0]]
        self.live_files -= 1
        self.images[current[1]][3] -= 1
        return OK

    # -- observation -----------------------------------------------------
    def _inspect(self, _event):
        images = []
        for epoch in sorted(self.images):
            resident = self.images[epoch]
            images.append([epoch, len(resident[1]), resident[2], resident[3]])
        return {'ok': True, 'active': self.active, 'images': images,
                'units': self.live_units, 'contexts': self.live_contexts,
                'connections': self.live_connections,
                'packets': self.live_packets, 'files': self.live_files}

    def event(self, event):
        try:
            return self._handlers[event['op']](event)
        except KeyError:
            return REJECTED
        except Exception:
            return REJECTED
